class Solution {
    public int[] numMovesStonesII(int[] stones){
        Arrays.sort(stones);
        int n=stones.length,maximum=Math.max(stones[n-2]-stones[0],stones[n-1]-stones[1])-(n-2),minimum=n,left=0;
        for(int right=0;right<n;right++){
            while(stones[right]-stones[left]+1>n)left++;
            int count=right-left+1;
            minimum=Math.min(minimum,count==n-1&&stones[right]-stones[left]==n-2?2:n-count);
        }
        return new int[]{
            minimum,maximum
        };
    }
}

code.kotlin:
class Solution {
    fun numMovesStonesII(stones:IntArray):IntArray{
        stones.sort();
        val n=stones.size;
        val maximum=maxOf(stones[n-2]-stones[0],stones[n-1]-stones[1])-(n-2);
        var minimum=n;
        var left=0;
        for(right in stones.indices){
            while(stones[right]-stones[left]+1>n)left++;
            val count=right-left+1;
            minimum=minOf(minimum,if(count==n-1&&stones[right]-stones[left]==n-2)2 else n-count)
        };
        return intArrayOf(minimum,maximum)
    }
}

